        if (bag == NULL) {
                gnutls_assert();
                return GNUTLS_E_INVALID_REQUEST;
        }

        if (bag->element[0].type != GNUTLS_BAG_ENCRYPTED) {
                gnutls_assert();
                return GNUTLS_E_INVALID_REQUEST;
